mapper.insert:
INSERT INTO WELFARE (
    PLCY_NO, LCLSF_NM, MCLSF_NM, MRG_STTS_CD, SCHOOL_CD, PLCY_MAJOR_CD, JOB_CD, SBIZ_CD, SPRT_TRGT_MIN_AGE,
    SPRT_TRGT_MAX_AGE, SPRT_TRGT_AGE_LMT_YN, EARN_MIN_AMT, EARN_MAX_AMT, EARN_ETC_CN, FULL_DATA
) VALUES (
    #{plcyNo}, #{lclsfNm}, #{mclsfNm}, #{mrgSttsCd}, #{schoolCd}, #{plcyMajorCd}, #{jobCd}, #{sbizCd}, #{sprtTrgtMinAge},
    #{sprtTrgtMaxAge}, #{sprtTrgtAgeLmtYn}, #{earnMinAmt}, #{earnMaxAmt}, #{earnEtcCn}, #{fullData}
)

mapper.select:
SELECT w.WELFARE_ID AS welfareId, w.LCLSF_NM AS lclsfNm, JSON_VALUE(w.FULL_DATA, '$.plcyNm') AS plcyNm, JSON_VALUE(w.FULL_DATA, '$.aplyYmd') AS aplyYmd, JSON_VALUE(w.FULL_DATA, '$.sprvsnInstCdNm') AS sprvsnInstCdNm, COUNT(wi.WELFARE_ID) AS wishCount FROM WELFARE w LEFT JOIN WISH wi ON w.WELFARE_ID = wi.WELFARE_ID WHERE 1=1
AND JSON_VALUE(w.FULL_DATA, '$.plcyNm') LIKE '%' || #{keyword} || '%'
AND (
(w.LCLSF_NM LIKE '%' || #{cat} || '%' OR w.LCLSF_NM LIKE '%참여권리%' OR w.LCLSF_NM LIKE '%복지문화%' OR w.LCLSF_NM LIKE '%교육･직업훈련%' )
)
AND (
JSON_VALUE(w.FULL_DATA, '$.zipCd') LIKE #{r} || '%'
)
AND w.SPRT_TRGT_MIN_AGE <= #{ageMax} AND w.SPRT_TRGT_MAX_AGE >= #{ageMin}
AND (
JSON_VALUE(w.FULL_DATA, '$.earnCndSeCd') = #{i}
)
AND (
w.JOB_CD LIKE '%' || #{j} || '%'
)
GROUP BY w.WELFARE_ID, w.LCLSF_NM, JSON_VALUE(w.FULL_DATA, '$.plcyNm'), JSON_VALUE(w.FULL_DATA, '$.aplyYmd'), JSON_VALUE(w.FULL_DATA, '$.sprvsnInstCdNm')
ORDER BY wishCount DESC, w.WELFARE_ID DESC
ORDER BY w.WELFARE_ID DESC
OFFSET #{offset} ROWS FETCH NEXT #{limit} ROWS ONLY

        SELECT COUNT(*) FROM WELFARE
        WHERE 1=1

            AND JSON_VALUE(FULL_DATA, '$.plcyNm') LIKE '%' || #{keyword} || '%'


            AND (

                    (LCLSF_NM LIKE '%' || #{cat} || '%'

                        OR LCLSF_NM LIKE '%참여권리%'


                        OR LCLSF_NM LIKE '%복지문화%'


                        OR LCLSF_NM LIKE '%교육･직업훈련%'

                    )

            )


            AND (

                    JSON_VALUE(FULL_DATA, '$.zipCd') LIKE #{r} || '%'

            )


		    AND (
		        (SPRT_TRGT_MIN_AGE = 0 AND SPRT_TRGT_MAX_AGE = 0)
		        OR (SPRT_TRGT_MIN_AGE <= #{ageMax} AND SPRT_TRGT_MAX_AGE >= #{ageMin})
		    )


            AND (

                    JSON_VALUE(FULL_DATA, '$.earnCndSeCd') = #{i}

            )


            AND (

                    JOB_CD LIKE '%' || #{j} || '%'

            )

SELECT * FROM ( SELECT w.WELFARE_ID AS welfareId, w.LCLSF_NM AS lclsfNm, JSON_VALUE(w.FULL_DATA, '$.plcyNm') AS plcyNm, JSON_VALUE(w.FULL_DATA, '$.aplyYmd') AS aplyYmd, JSON_VALUE(w.FULL_DATA, '$.sprvsnInstCdNm') AS sprvsnInstCdNm FROM WELFARE w
AND w.LCLSF_NM IN ( SELECT DISTINCT w2.LCLSF_NM FROM WELFARE w2 JOIN WISH wi ON w2.WELFARE_ID = wi.WELFARE_ID WHERE wi.MEMBER_ID = #{memberId} )
AND EXISTS ( SELECT 1 FROM POLICY_REGION PR WHERE PR.WELFARE_ID = w.WELFARE_ID AND PR.ZIP_CD LIKE #{region} || '%' )
AND JSON_VALUE(w.FULL_DATA, '$.emplmSttsCd') = #{jobStatus}
AND JSON_VALUE(w.FULL_DATA, '$.ernIncmSeCd') = #{incomeLevel}
ORDER BY DBMS_RANDOM.VALUE ) WHERE ROWNUM <= 4
